#include <cmath>
#include <iostream>

double newtonRaphson(double x0, double tol, int maxIter) {
    double x = x0;
    for (int iter = 0; iter < maxIter; ++iter) {
        double fx = f(x);
        double dfx = df(x);

        if (std::fabs(dfx) < 1e-9) {
            std::cerr << "Error: Derivative near zero!" << std::endl;
            return NAN;
        }

        double h = fx / dfx;
        double x_next = x - h;

        if (std::fabs(h) < tol) {
            return x_next;
        }
        x = x_next;
    }
    std::cerr << "Warning: Did not converge within max iterations!" << std::endl;
    return x;
}

