double newtonRaphson(double x0, double tol, int maxIter) {
    double x = x0;
    int count = 0;
    while (count < maxIter) {
        double df_val = df(x);
        if (fabs(df_val) < 1e-12) {
            printf("Derivative too small\n");
            return x;
        }
        double x_new = x - f(x) / df_val;
        if (fabs(x_new - x) < tol) return x_new;
        x = x_new;
        count++;
    }
    return x;
}

double newtonRaphson(double x0, double tol, int maxIter) {
    double x = x0;
    for (int i = 0; i < maxIter; i++) {
        double f_prime = df(x);
        if (fabs(f_prime) < 1e-7) return -9999.0; // Status error code
        double step = f(x) / f_prime;
        x -= step;
        if (fabs(step) < tol) return x;
    }
    return x;
}
